#!/usr/bin/env python3
"""Append a snapshot of Kalshi prices for one NFL team's next game.

Usage: python3 snapshot.py BUF

Fetches the moneyline, spread, and total markets for the team's next open game
from Kalshi's public API (GET only, no key) and appends one row per market to
data/snapshots.csv. Prices are stored in integer cents.
"""

import csv
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation

API_BASE = "https://api.elections.kalshi.com/trade-api/v2"
DATA_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")
CSV_PATH = os.path.join(DATA_DIR, "snapshots.csv")

# Kalshi's NFL team codes (note JAC, LAR, LV, WAS; not JAX, LA, OAK, WSH).
TEAM_CODES = {
    "ARI", "ATL", "BAL", "BUF", "CAR", "CHI", "CIN", "CLE",
    "DAL", "DEN", "DET", "GB", "HOU", "IND", "JAC", "KC",
    "LAC", "LAR", "LV", "MIA", "MIN", "NE", "NO", "NYG",
    "NYJ", "PHI", "PIT", "SEA", "SF", "TB", "TEN", "WAS",
}

MONEYLINE_SERIES = "KXNFLGAME"
# Spec market_type -> Kalshi series. Events share a suffix across series,
# e.g. KXNFLGAME-26NOV09BUFMIN / KXNFLSPREAD-26NOV09BUFMIN / KXNFLTOTAL-26NOV09BUFMIN.
SERIES_BY_TYPE = [
    ("moneyline", "KXNFLGAME"),
    ("spread", "KXNFLSPREAD"),
    ("total", "KXNFLTOTAL"),
]

FIELDS = [
    "timestamp", "event_ticker", "market_ticker", "market_type",
    "label", "yes_bid", "yes_ask", "last", "volume",
]


class SnapshotError(Exception):
    """A problem that should be reported to the user without a traceback."""


def api_get(path, params):
    url = API_BASE + path + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(
        url, headers={"Accept": "application/json", "User-Agent": "nfl-line-tracker/0.1"}
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.load(resp)
    except urllib.error.HTTPError as e:
        raise SnapshotError("Kalshi API returned HTTP %d for %s" % (e.code, url))
    except urllib.error.URLError as e:
        raise SnapshotError("could not reach Kalshi API (%s)" % e.reason)
    except (ValueError, OSError) as e:
        raise SnapshotError("bad response from Kalshi API for %s (%s)" % (url, e))


def get_all(path, params, key):
    """Follow Kalshi's cursor pagination and return every item under `key`."""
    items = []
    cursor = ""
    while True:
        page_params = dict(params)
        if cursor:
            page_params["cursor"] = cursor
        data = api_get(path, page_params)
        items.extend(data.get(key) or [])
        cursor = data.get("cursor") or ""
        if not cursor:
            return items


def find_next_event(team):
    """Return the moneyline event dict for the team's earliest open game."""
    events = get_all(
        "/events",
        {"series_ticker": MONEYLINE_SERIES, "status": "open",
         "with_nested_markets": "true", "limit": 200},
        "events",
    )
    suffix = "-" + team
    games = []
    for event in events:
        markets = event.get("markets") or []
        # Match on market tickers (…-BUF) rather than splitting "BUFMIN",
        # which is ambiguous with two-letter codes like GB or KC.
        if any(m.get("ticker", "").endswith(suffix) for m in markets):
            times = [m.get("expected_expiration_time") or "" for m in markets]
            games.append((min(times), event["event_ticker"], event))
    if not games:
        raise SnapshotError("no open Kalshi NFL game found for %s (bye week or off-season?)" % team)
    games.sort(key=lambda g: (g[0], g[1]))
    return games[0][2]


def to_cents(dollars):
    """'0.3800' -> 38. Returns '' if the field is missing or unparseable."""
    if dollars in (None, ""):
        return ""
    try:
        return int((Decimal(str(dollars)) * 100).to_integral_value())
    except (InvalidOperation, ValueError):
        return ""


def to_volume(value):
    """'218304.60' -> 218304 (whole contracts, truncated)."""
    if value in (None, ""):
        return ""
    try:
        return int(Decimal(str(value)))
    except (InvalidOperation, ValueError):
        return ""


def build_rows(team):
    game = find_next_event(team)
    game_suffix = game["event_ticker"].split("-", 1)[1]  # e.g. 26NOV09BUFMIN
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    rows = []
    for market_type, series in SERIES_BY_TYPE:
        event_ticker = series + "-" + game_suffix
        markets = get_all("/markets", {"event_ticker": event_ticker, "limit": 1000}, "markets")
        if not markets:
            print("warning: no %s markets found for %s" % (market_type, event_ticker), file=sys.stderr)
            continue
        for m in sorted(markets, key=lambda m: m.get("ticker", "")):
            rows.append({
                "timestamp": timestamp,
                "event_ticker": m.get("event_ticker", event_ticker),
                "market_ticker": m.get("ticker", ""),
                "market_type": market_type,
                "label": m.get("yes_sub_title") or m.get("title") or "",
                "yes_bid": to_cents(m.get("yes_bid_dollars")),
                "yes_ask": to_cents(m.get("yes_ask_dollars")),
                "last": to_cents(m.get("last_price_dollars")),
                "volume": to_volume(m.get("volume_fp")),
            })
    return game, rows


def append_rows(rows):
    os.makedirs(DATA_DIR, exist_ok=True)
    write_header = not os.path.exists(CSV_PATH) or os.path.getsize(CSV_PATH) == 0
    with open(CSV_PATH, "a", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS)
        if write_header:
            writer.writeheader()
        writer.writerows(rows)


def main(argv):
    if len(argv) != 2:
        print("usage: python3 snapshot.py TEAM   (e.g. BUF)", file=sys.stderr)
        return 2

    team = argv[1].strip().upper()
    if team not in TEAM_CODES:
        print("error: unknown team code %r. Valid codes: %s"
              % (argv[1], ", ".join(sorted(TEAM_CODES))), file=sys.stderr)
        return 1

    try:
        game, rows = build_rows(team)
    except SnapshotError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1

    if not rows:
        print("error: no markets found for %s; nothing written" % game["event_ticker"], file=sys.stderr)
        return 1

    append_rows(rows)
    counts = {}
    for r in rows:
        counts[r["market_type"]] = counts.get(r["market_type"], 0) + 1
    summary = ", ".join("%d %s" % (counts[t], t) for t, _ in SERIES_BY_TYPE if t in counts)
    print("%s: %s (%s). Appended %d rows (%s) to %s"
          % (team, game.get("title", ""), game["event_ticker"], len(rows), summary,
             os.path.relpath(CSV_PATH)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

